  },
  "plugins": {
    "updater": {
      "pubkey": "REPLACE_WITH_ED25519_PUBLIC_KEY",
      "endpoints": [
        "https://github.com/FSM1/cipher-box/releases/latest/download/latest.json"
      ]
    },
    "deep-link": {
      "desktop": {
        "schemes": [
          "cipherbox"
        ]
      }
    }
  }
}

