 1→//! Auto-update integration using tauri-plugin-updater.
 2→//!
 3→//! Checks for updates on launch (with 5-second delay), downloads in background,
 4→//! and notifies via system notification. Manual check available from tray menu.
 5→
 6→use tauri::AppHandle;
 7→use tauri_plugin_updater::UpdaterExt;
 8→
 9→/// Check for updates on app launch. Spawns async task with 5s delay.
10→pub fn check_on_launch(app: &AppHandle) {
11→    let handle = app.clone();
12→    tauri::async_runtime::spawn(async move {
13→        // Small delay to avoid competing with login/mount startup
14→        tokio::time::sleep(std::time::Duration::from_secs(5)).await;
15→
16→        if let Err(e) = do_update_check(&handle).await {
17→            log::warn!("Update check failed: {}", e);
18→        }
19→    });
20→}
21→
22→/// Manual check triggered from tray "Check for Updates..." menu item.
23→pub fn manual_check(app: &AppHandle) {
24→    let handle = app.clone();
25→    tauri::async_runtime::spawn(async move {
26→        match do_update_check(&handle).await {
27→            Ok(found) => {
28→                if !found {
29→                    // No update available -- notify user since they asked explicitly
30→                    use tauri_plugin_notification::NotificationExt;
31→                    let _ = handle
32→                        .notification()
33→                        .builder()
34→                        .title("CipherBox")
35→                        .body("You are running the latest version.")
36→                        .show();
37→                }
38→            }
39→            Err(e) => {
40→                use tauri_plugin_notification::NotificationExt;
41→                let _ = handle
42→                    .notification()
43→                    .builder()
44→                    .title("CipherBox")
45→                    .body("Update check failed. Please try again later.")
46→                    .show();
47→                log::warn!("Manual update check failed: {}", e);
48→            }
49→        }
50→    });
51→}
52→
53→/// Perform the actual update check, download, and notification.
54→/// Returns Ok(true) if an update was found and downloaded, Ok(false) if no update.
55→async fn do_update_check(app: &AppHandle) -> Result<bool, Box<dyn std::error::Error>> {
56→    let updater = app.updater()?;
57→    let update = updater.check().await?;
58→
59→    if let Some(update) = update {
60→        log::info!("Update available: v{}", update.version);
61→
62→        // Download and install (stages for next restart on macOS/Linux)
63→        let version = update.version.clone();
64→        update
65→            .download_and_install(
66→                |chunk_length, content_length| {
67→                    log::debug!(
68→                        "Downloading update: {} / {:?} bytes",
69→                        chunk_length,
70→                        content_length
71→                    );
72→                },
73→                || {
74→                    log::info!("Update downloaded, pending install on restart");
75→                },
76→            )
77→            .await?;
78→
79→        // Notify user via system notification
80→        use tauri_plugin_notification::NotificationExt;
81→        let _ = app
82→            .notification()
83→            .builder()
84→            .title("CipherBox Update Ready")
85→            .body(&format!(
86→                "CipherBox v{} is ready. It will be installed on next restart.",
87→                version
88→            ))
89→            .show();
90→
91→        Ok(true)
92→    } else {
93→        log::info!("No update available (current version is latest)");
94→        Ok(false)
95→    }
96→}
