  1→//! FUSE filesystem trait implementation for CipherBoxFS.
  2→//!
  3→//! Delegates to category-specific modules:
  4→//! - `read_ops`: init, destroy, lookup, getattr, open, read, release, flush, access, getxattr, listxattr
  5→//! - `write_ops`: setattr, write, create, unlink, mkdir, rmdir, rename
  6→//! - `dir_ops`: readdir, opendir, releasedir, statfs
  7→
  8→#[cfg(feature = "fuse")]
  9→pub(crate) mod implementation {
 10→    use fuser::{
 11→        Filesystem, ReplyAttr, ReplyCreate, ReplyData, ReplyDirectory,
 12→        ReplyEntry, ReplyEmpty, ReplyOpen, ReplyStatfs, ReplyWrite, ReplyXattr, Request,
 13→    };
 14→    use std::ffi::OsStr;
 15→    use std::time::{Duration, SystemTime};
 16→
 17→    use crate::CipherBoxFS;
 18→
 19→    /// TTL for FUSE attribute/entry cache replies on files.
 20→    pub const FILE_TTL: Duration = Duration::from_secs(60);
 21→
 22→    /// TTL for directory attribute/entry cache replies.
 23→    pub const DIR_TTL: Duration = Duration::from_secs(0);
 24→
 25→    pub fn ttl_for_is_dir(is_dir: bool) -> Duration {
 26→        if is_dir { DIR_TTL } else { FILE_TTL }
 27→    }
 28→
 29→    pub fn current_uid() -> u32 {
 30→        unsafe { libc::getuid() }
 31→    }
 32→
 33→    pub fn current_gid() -> u32 {
 34→        unsafe { libc::getgid() }
 35→    }
 36→
 37→    pub const NETWORK_TIMEOUT: Duration = Duration::from_secs(3);
 38→
 39→    pub fn block_with_timeout<F, T>(rt: &tokio::runtime::Handle, fut: F) -> Result<T, String>
 40→    where
 41→        F: std::future::Future<Output = Result<T, String>>,
 42→    {
 43→        rt.block_on(async {
 44→            match tokio::time::timeout(NETWORK_TIMEOUT, fut).await {
 45→                Ok(result) => result,
 46→                Err(_) => Err("Operation timed out".to_string()),
 47→            }
 48→        })
 49→    }
 50→
 51→    pub fn fetch_and_decrypt_file_content(
 52→        fs: &CipherBoxFS,
 53→        cid: &str,
 54→        encrypted_file_key_hex: &str,
 55→        iv_hex: &str,
 56→        encryption_mode: &str,
 57→    ) -> Result<Vec<u8>, String> {
 58→        let api = fs.api.clone();
 59→        let private_key = fs.private_key.clone();
 60→        let cid_owned = cid.to_string();
 61→        let key_hex = encrypted_file_key_hex.to_string();
 62→        let iv_hex_owned = iv_hex.to_string();
 63→        let mode = encryption_mode.to_string();
 64→        let rt = fs.rt.clone();
 65→
 66→        block_with_timeout(&rt, async {
 67→            let encrypted_bytes = cipherbox_api_client::ipfs::fetch_content(&api, &cid_owned)
 68→                .await.map_err(|e| format!("{}", e))?;
 69→            let encrypted_file_key = hex::decode(&key_hex).map_err(|_| "Invalid file key hex".to_string())?;
 70→            let file_key = zeroize::Zeroizing::new(
 71→                cipherbox_crypto::unwrap_key(&encrypted_file_key, &private_key)
 72→                    .map_err(|e| format!("File key unwrap failed: {}", e))?,
 73→            );
 74→            let file_key_arr: [u8; 32] = file_key.as_slice().try_into()
 75→                .map_err(|_| "Invalid file key length".to_string())?;
 76→
 77→            let plaintext = if mode == "CTR" {
 78→                let iv = hex::decode(&iv_hex_owned).map_err(|_| "Invalid file IV hex".to_string())?;
 79→                let iv_arr: [u8; 16] = iv.try_into().map_err(|_| "Invalid CTR IV length (expected 16)".to_string())?;
 80→                cipherbox_crypto::decrypt_aes_ctr(&encrypted_bytes, &file_key_arr, &iv_arr)
 81→                    .map_err(|e| format!("CTR file decryption failed: {}", e))?
 82→            } else {
 83→                let iv = hex::decode(&iv_hex_owned).map_err(|_| "Invalid file IV hex".to_string())?;
 84→                let iv_arr: [u8; 12] = iv.try_into().map_err(|_| "Invalid GCM IV length (expected 12)".to_string())?;
 85→                cipherbox_crypto::decrypt_aes_gcm(&encrypted_bytes, &file_key_arr, &iv_arr)
 86→                    .map_err(|e| format!("GCM file decryption failed: {}", e))?
 87→            };
 88→            Ok(plaintext)
 89→        })
 90→    }
 91→
 92→    pub async fn fetch_and_decrypt_content_async(
 93→        api: &cipherbox_api_client::ApiClient,
 94→        cid: &str,
 95→        encrypted_file_key_hex: &str,
 96→        iv_hex: &str,
 97→        encryption_mode: &str,
 98→        private_key: &[u8],
 99→    ) -> Result<Vec<u8>, String> {
100→        let encrypted_bytes = cipherbox_api_client::ipfs::fetch_content(api, cid)
101→            .await.map_err(|e| format!("{}", e))?;
102→        let encrypted_file_key = hex::decode(encrypted_file_key_hex)
103→            .map_err(|_| "Invalid file key hex".to_string())?;
104→        let file_key = zeroize::Zeroizing::new(
105→            cipherbox_crypto::unwrap_key(&encrypted_file_key, private_key)
106→                .map_err(|e| format!("File key unwrap failed: {}", e))?,
107→        );
108→        let file_key_arr: [u8; 32] = file_key.as_slice().try_into()
109→            .map_err(|_| "Invalid file key length".to_string())?;
110→
111→        let plaintext = if encryption_mode == "CTR" {
112→            let iv = hex::decode(iv_hex).map_err(|_| "Invalid file IV hex".to_string())?;
113→            let iv_arr: [u8; 16] = iv.try_into().map_err(|_| "Invalid CTR IV length (expected 16)".to_string())?;
114→            cipherbox_crypto::decrypt_aes_ctr(&encrypted_bytes, &file_key_arr, &iv_arr)
115→                .map_err(|e| format!("CTR decryption failed: {}", e))?
116→        } else {
117→            let iv = hex::decode(iv_hex).map_err(|_| "Invalid file IV hex".to_string())?;
118→            let iv_arr: [u8; 12] = iv.try_into().map_err(|_| "Invalid GCM IV length (expected 12)".to_string())?;
119→            cipherbox_crypto::decrypt_aes_gcm(&encrypted_bytes, &file_key_arr, &iv_arr)
120→                .map_err(|e| format!("GCM decryption failed: {}", e))?
121→        };
122→        Ok(plaintext)
123→    }
