392→                    reply.data(&content[start..end]);
393→                }
394→                return;
395→            }
396→            reply.data(&[]);
397→            return;
398→        }
399→
400→        if let Some(handle) = fs.open_files.get(&fh) {

600→                            }
601→                            _ => None,
602→                        },
603→                        None => None,
604→                    }
605→                } else {
606→                    None
607→                };
608→
609→            fs.inodes.remove(ino);
