699→                .unwrap_or(false);
700→
701→            if needs_flush {
702→                let is_new_file = fs.inodes.get(ino)
703→                    .map(|i| match &i.kind {
704→                        InodeKind::File { cid, .. } => cid.is_empty(),
705→                        _ => false,
706→                    })
707→                    .unwrap_or(false);
708→                let handle = fs.open_files.remove(&fh).unwrap();
709→
710→                let prepare_result = (|| -> Result<(), String> {
711→                    let plaintext = handle.read_all()?;
712→                    let mut file_key = cipherbox_crypto::utils::generate_file_key();
