720→                    cipherbox_crypto::utils::clear_bytes(&mut file_key);
721→
722→                    let (old_file_cid, _old_encrypted_key, _old_iv, old_size, old_mode,
723→                         existing_versions, file_ipns_private_key, file_meta_ipns_name) =
724→                        fs.inodes.get(ino).map(|inode| match &inode.kind {
725→                            InodeKind::File {
726→                                cid, encrypted_file_key, iv, size, encryption_mode,
727→                                versions, file_ipns_private_key, file_meta_ipns_name, ..
728→                            } => (
729→                                if cid.is_empty() { None } else { Some(cid.clone()) },
730→                                encrypted_file_key.clone(), iv.clone(), *size,
731→                                encryption_mode.clone(), versions.clone(),
732→                                file_ipns_private_key.clone(), file_meta_ipns_name.clone(),
733→                            ),
734→                            _ => (None, String::new(), String::new(), 0, "GCM".to_string(), None, None, None),
735→                        }).unwrap_or((None, String::new(), String::new(), 0, "GCM".to_string(), None, None, None));
736→
737→                    let encrypted_file_key_hex = hex::encode(&wrapped_key);
738→                    let iv_hex = hex::encode(&iv);
739→                    let file_size = plaintext.len() as u64;
740→                    let file_name = fs.inodes.get(ino).map(|i| i.name.clone()).unwrap_or_default();
741→                    let mime_type = mime_from_extension(&file_name);
742→
743→                    let now_ms = SystemTime::now()
744→                        .duration_since(UNIX_EPOCH)
745→                        .unwrap_or_default()
746→                        .as_millis() as u64;
747→
748→                    let should_version = if let Some(ref versions) = existing_versions {
749→                        if let Some(newest) = versions.first() {
750→                            now_ms.saturating_sub(newest.timestamp) >= VERSION_COOLDOWN_MS
751→                        } else {
752→                            old_file_cid.as_ref().is_some_and(|c| !c.is_empty())
753→                        }
754→                    } else {
755→                        old_file_cid.as_ref().is_some_and(|c| !c.is_empty())
756→                    };
757→
758→                    let (new_versions, pruned_cids) = if should_version {
759→                        if let Some(ref old_c) = old_file_cid {
760→                            if !old_c.is_empty() {
761→                                let version_entry = cipherbox_core::folder::VersionEntry {
762→                                    cid: old_c.clone(),
763→                                    file_key_encrypted: _old_encrypted_key.clone(),
764→                                    file_iv: _old_iv.clone(),
765→                                    size: old_size,
766→                                    timestamp: now_ms,
767→                                    encryption_mode: old_mode.clone(),
768→                                };
769→                                let mut versions = vec![version_entry];
770→                                versions.extend(existing_versions.unwrap_or_default());
771→                                let pruned: Vec<String> = if versions.len() > MAX_VERSIONS_PER_FILE {
772→                                    versions.split_off(MAX_VERSIONS_PER_FILE).into_iter().map(|v| v.cid).collect()
773→                                } else {
774→                                    vec![]
775→                                };
776→                                (Some(versions), pruned)
777→                            } else {
778→                                (existing_versions, vec![])
779→                            }
780→                        } else {
781→                            (existing_versions, vec![])
782→                        }
783→                    } else {
784→                        (existing_versions, vec![])
785→                    };
786→
787→                    let versions_for_meta = new_versions.as_ref()
788→                        .filter(|v| !v.is_empty())
789→                        .cloned();
790→
791→                    if let Some(inode) = fs.inodes.get_mut(ino) {
792→                        let cached_hex = match &inode.kind {
793→                            InodeKind::File { file_ipns_key_encrypted_hex, .. } => file_ipns_key_encrypted_hex.clone(),
794→                            _ => None,
795→                        };
796→                        inode.kind = InodeKind::File {
797→                            cid: String::new(),
798→                            encrypted_file_key: encrypted_file_key_hex.clone(),
799→                            iv: iv_hex.clone(),
800→                            size: file_size,
801→                            encryption_mode: "GCM".to_string(),
802→                            file_meta_ipns_name: file_meta_ipns_name.clone(),
803→                            file_meta_resolved: true,
804→                            file_ipns_private_key: file_ipns_private_key.clone(),
805→                            file_ipns_key_encrypted_hex: cached_hex,
806→                            versions: versions_for_meta.clone(),
807→                        };
808→                        // Bump generation so stale background uploads (from a
809→                        // prior truncate-to-zero flush) are rejected by
810→                        // drain_upload_completions.
811→                        inode.write_generation += 1;
812→                        inode.attr.size = file_size;
813→                        inode.attr.blocks = (file_size + 511) / 512;
814→                        inode.attr.mtime = SystemTime::now();
815→                    }
816→
817→                    fs.pending_content.insert(ino, plaintext);
818→
819→                    let write_gen = fs.inodes.get(ino)
820→                        .map(|i| i.write_generation)
821→                        .unwrap_or(0);
822→                    let parent_ino = fs.inodes.get(ino).map(|i| i.parent_ino).unwrap_or(ROOT_INO);
823→                    let folder_key_for_file_meta = fs.get_folder_key(parent_ino);
824→                    fs.queue_publish(parent_ino, true);
825→
826→                    let api = fs.api.clone();
827→                    let rt = fs.rt.clone();
828→                    let upload_tx = fs.upload_tx.clone();
829→                    let coordinator = fs.publish_coordinator.clone();
830→                    let tee_public_key = fs.tee_public_key.clone();
831→                    let tee_key_epoch = fs.tee_key_epoch;
832→
833→                    let file_meta = cipherbox_core::folder::FileMetadata {
834→                        version: "v1".to_string(),
835→                        cid: String::new(),
836→                        file_key_encrypted: encrypted_file_key_hex,
837→                        file_iv: iv_hex,
838→                        size: file_size,
839→                        mime_type,
840→                        encryption_mode: "GCM".to_string(),
841→                        created_at: now_ms,
842→                        modified_at: now_ms,
843→                        versions: versions_for_meta,
844→                    };
845→
846→                    std::thread::spawn(move || {
847→                        let result = rt.block_on(async {
848→                            let file_cid = cipherbox_api_client::ipfs::upload_content(&api, &ciphertext).await.map_err(|e| e.to_string())?;
849→                            log::info!("File uploaded: ino {} -> CID {}", ino, file_cid);
850→
851→                            let _ = upload_tx.send(crate::UploadComplete {
852→                                ino,
853→                                new_cid: file_cid.clone(),
854→                                parent_ino,
855→                                old_file_cid,
856→                                pruned_cids,
857→                                write_generation: write_gen,
858→                            });
859→
860→                            if let (Some(ipns_key), Some(ipns_name), Some(folder_key)) =
861→                                (&file_ipns_private_key, &file_meta_ipns_name, &folder_key_for_file_meta)
862→                            {
863→                                let mut file_meta_with_cid = file_meta;
864→                                file_meta_with_cid.cid = file_cid;
865→                                if let Err(e) = publish_file_metadata(
866→                                    &api, &file_meta_with_cid, folder_key, ipns_key, ipns_name, &coordinator,
867→                                    tee_public_key.as_deref(),
868→                                    tee_key_epoch,
869→                                    is_new_file,
870→                                ).await {
871→                                    log::warn!("Per-file IPNS publish failed for ino {}: {}", ino, e);
872→                                }
873→                            }
874→
875→                            Ok::<(), String>(())
876→                        });
877→
878→                        if let Err(e) = result {
879→                            log::error!("Background upload failed for ino {}: {}", ino, e);
880→                        }
881→                    });
882→
883→                    Ok(())
884→                })();
885→
886→                if let Err(e) = prepare_result {
887→                    log::error!("File upload preparation failed for ino {}: {}", ino, e);
888→                }
889→
890→                handle.cleanup();
891→            }
892→        }
893→    }
