895→    /// rename handler
896→    pub fn handle_rename(
897→        ctx: &WinFspContext,
898→        file_name: &U16CStr,
899→        new_file_name: &U16CStr,
900→        replace_if_exists: bool,
901→    ) -> Result<(), FspError> {
902→        let old_path = file_name.to_string_lossy();
903→        let new_path = new_file_name.to_string_lossy();
904→
905→        let mut fs = ctx.inner.lock().unwrap();
906→
907→        let (source_ino, old_parent_ino) = resolve_path(&fs, &old_path)
908→            .ok_or(status_object_name_not_found())?;
909→
910→        let (new_parent_path, new_name) = split_path(&new_path);
911→        let (new_parent_ino, _) = resolve_path(&fs, new_parent_path)
912→            .ok_or(status_object_name_not_found())?;
913→
914→        if let Some(dest_ino) = fs.inodes.find_child(new_parent_ino, new_name) {
915→            if !replace_if_exists {
916→                return Err(status_object_name_collision());
917→            }
918→            if let Some(dest_inode) = fs.inodes.get(dest_ino) {
919→                match &dest_inode.kind {
920→                    InodeKind::Folder { .. } => {
921→                        if let Some(ref children) = dest_inode.children {
922→                            if !children.is_empty() {
923→                                return Err(status_directory_not_empty());
924→                            }
925→                        }
926→                    }
927→                    InodeKind::File { cid, .. } => {
928→                        if !cid.is_empty() {
929→                            let cid_clone = cid.clone();
930→                            let api = fs.api.clone();
931→                            fs.rt.spawn(async move {
932→                                let _ = cipherbox_api_client::ipfs::unpin_content(&api, &cid_clone).await;
933→                            });
934→                        }
935→                    }
936→                    _ => {}
937→                }
938→            }
939→            fs.inodes.remove(dest_ino);
940→        }
941→
942→        let old_name = fs.inodes.get(source_ino).map(|i| i.name.clone()).unwrap_or_default();
943→        fs.inodes.name_to_ino.remove(&(
944→            old_parent_ino,
945→            crate::inode::normalize_name(&old_name),
946→        ));
947→
948→        if let Some(inode) = fs.inodes.get_mut(source_ino) {
949→            inode.name = new_name.to_string();
950→            inode.parent_ino = new_parent_ino;
951→            inode.attr.ctime = SystemTime::now();
952→        }
953→
954→        fs.inodes.name_to_ino.insert(
955→            (new_parent_ino, crate::inode::normalize_name(new_name)),
956→            source_ino,
957→        );
958→
959→        if old_parent_ino != new_parent_ino {
960→            if let Some(old_parent) = fs.inodes.get_mut(old_parent_ino) {
961→                if let Some(ref mut children) = old_parent.children {
962→                    children.retain(|&c| c != source_ino);
963→                }
964→                old_parent.attr.mtime = SystemTime::now();
965→                old_parent.attr.ctime = SystemTime::now();
966→            }
967→            if let Some(new_parent) = fs.inodes.get_mut(new_parent_ino) {
968→                if let Some(ref mut children) = new_parent.children {
969→                    children.push(source_ino);
970→                }
971→                new_parent.attr.mtime = SystemTime::now();
972→                new_parent.attr.ctime = SystemTime::now();
973→            }
974→            if let Err(e) = fs.update_folder_metadata(old_parent_ino) {
975→                log::error!("Failed to update old parent metadata after rename: {}", e);
976→            }
977→            if let Err(e) = fs.update_folder_metadata(new_parent_ino) {
978→                log::error!("Failed to update new parent metadata after rename: {}", e);
979→            }
980→        } else {
981→            if let Some(parent_inode) = fs.inodes.get_mut(old_parent_ino) {
982→                parent_inode.attr.mtime = SystemTime::now();
983→                parent_inode.attr.ctime = SystemTime::now();
984→            }
985→            if let Err(e) = fs.update_folder_metadata(old_parent_ino) {
986→                log::error!("Failed to update parent metadata after rename: {}", e);
987→            }
988→        }
989→
990→        Ok(())
991→    }
