191→    /// Fetch, decrypt, and return file content synchronously.
192→    pub fn fetch_and_decrypt_file_content(
193→        fs: &CipherBoxFS,
194→        cid: &str,
195→        encrypted_file_key_hex: &str,
196→        iv_hex: &str,
197→        encryption_mode: &str,
198→    ) -> Result<Vec<u8>, String> {
199→        let api = fs.api.clone();
200→        let private_key = fs.private_key.clone();

302→    pub async fn publish_file_metadata(
303→        api: &cipherbox_api_client::ApiClient,
304→        file_meta: &cipherbox_core::folder::FileMetadata,
305→        folder_key: &[u8],
306→        file_ipns_private_key: &zeroize::Zeroizing<Vec<u8>>,
307→        file_ipns_name: &str,
308→        coordinator: &crate::PublishCoordinator,
309→        tee_public_key: Option<&[u8]>,
310→        tee_key_epoch: Option<u32>,
311→        is_first_publish: bool,
312→    ) -> Result<(), String> {
313→        let folder_key_arr: [u8; 32] = folder_key.try_into().map_err(|_| {
314→            "Invalid folder key length for FileMetadata encryption".to_string()
315→        })?;
316→
317→        // Encrypt FileMetadata with parent folder key
318→        let sealed =
319→            cipherbox_core::folder::encrypt_file_metadata(file_meta, &folder_key_arr)
320→                .map_err(|e| format!("FileMetadata encryption failed: {}", e))?;
321→
322→        // Package as JSON envelope: { "iv": hex, "data": base64 }
323→        let iv_hex = hex::encode(&sealed[..12]);
324→        use base64::Engine;
325→        let data_base64 =
326→            base64::engine::general_purpose::STANDARD.encode(&sealed[12..]);
327→        let json = serde_json::json!({ "iv": iv_hex, "data": data_base64 });
328→        let json_bytes = serde_json::to_vec(&json)
329→            .map_err(|e| format!("FileMetadata JSON serialization failed: {}", e))?;
330→
331→        // Upload encrypted file metadata to IPFS
332→        let file_meta_cid =
333→            cipherbox_api_client::ipfs::upload_content(api, &json_bytes).await.map_err(|e| e.to_string())?;
334→
335→        // Resolve current IPNS sequence number
336→        let seq = coordinator
337→            .resolve_sequence(api, file_ipns_name)
338→            .await?;
339→
340→        // Create and sign IPNS record
341→        let ipns_key_arr: [u8; 32] = file_ipns_private_key
342→            .as_slice()
343→            .try_into()
344→            .map_err(|_| "Invalid file IPNS private key length".to_string())?;
345→        let new_seq = seq + 1;
346→        let value = format!("/ipfs/{}", file_meta_cid);
347→        let record = cipherbox_core::ipns::create_ipns_record(
348→            &ipns_key_arr,
349→            &value,
350→            new_seq,
351→            86_400_000,
352→        )
353→        .map_err(|e| format!("File IPNS record creation failed: {}", e))?;
354→        let marshaled = cipherbox_core::ipns::marshal_ipns_record(&record)
355→            .map_err(|e| format!("File IPNS record marshal failed: {}", e))?;
356→
357→        let record_b64 =
358→            base64::engine::general_purpose::STANDARD.encode(&marshaled);
359→
360→        // TEE enrollment on first publish only (same pattern as folder creation in write_ops.rs)
361→        let encrypted_ipns_for_tee = if is_first_publish {
362→            if let Some(tee_key) = tee_public_key {
363→                let wrapped = cipherbox_crypto::wrap_key(
364→                    file_ipns_private_key.as_slice(), tee_key
365→                ).map_err(|e| format!("TEE key wrapping failed: {}", e))?;
366→                Some(hex::encode(&wrapped))
367→            } else {
368→                None
369→            }
370→        } else {
371→            None
372→        };
373→        let has_tee_enrollment = encrypted_ipns_for_tee.is_some();
374→
375→        // Per-file IPNS publishes do not use conflict detection -- file metadata
376→        // is owned by the file's own IPNS keypair and conflicts are inherently
377→        // avoided by the per-file sequence number management.
378→        let req = cipherbox_api_client::IpnsPublishRequest {
379→            ipns_name: file_ipns_name.to_string(),
380→            record: record_b64,
381→            metadata_cid: file_meta_cid.clone(),
382→            encrypted_ipns_private_key: encrypted_ipns_for_tee,
383→            key_epoch: if has_tee_enrollment { tee_key_epoch } else { None },
384→            expected_sequence_number: None,
385→        };
386→        match cipherbox_api_client::ipns::publish_ipns(api, &req).await.map_err(|e| e.to_string())? {
387→            cipherbox_api_client::PublishResult::Success => {}
388→            cipherbox_api_client::PublishResult::Conflict { .. } => {
389→                log::warn!("Unexpected conflict on per-file IPNS publish for {}", file_ipns_name);
390→            }
391→        }
392→
393→        coordinator.record_publish(file_ipns_name, new_seq);
394→        log::info!("Per-file IPNS publish succeeded for {}", file_ipns_name);
395→
396→        Ok(())
397→    }
