130→/// Handle a menu item click by ID.
131→fn handle_menu_event(app: &AppHandle, id: &str) {
132→    use tauri_plugin_notification::NotificationExt;
133→    match id {
134→        "open" => {
135→            // Open ~/CipherBox in the platform file manager
136→            let mount_point = dirs::home_dir()
137→                .map(|h| h.join("CipherBox"))
138→                .unwrap_or_default();
139→            if !mount_point.exists() {
140→                log::warn!("Mount point {} does not exist — filesystem may not be mounted", mount_point.display());
141→                // Show notification instead of a confusing file manager error
142→                if let Err(e) = app.notification()
143→                    .builder()
144→                    .title("CipherBox")
145→                    .body("Vault is not mounted. Please sign in first.")
146→                    .show()
147→                {
148→                    log::error!("Failed to show notification: {}", e);
149→                }
150→                return;
151→            }
152→            #[cfg(target_os = "macos")]
153→            {
154→                if let Err(e) = std::process::Command::new("open")
155→                    .arg(mount_point.to_str().unwrap_or("~/CipherBox"))
156→                    .spawn()
157→                {
158→                    log::error!("Failed to open CipherBox in Finder: {}", e);
159→                }
160→            }
161→            #[cfg(target_os = "windows")]
162→            {
163→                if let Err(e) = std::process::Command::new("explorer.exe")
164→                    .arg(mount_point.to_str().unwrap_or_default())
165→                    .spawn()
166→                {
167→                    log::error!("Failed to open CipherBox in Explorer: {}", e);
168→                }
169→            }
170→            #[cfg(target_os = "linux")]
171→            {
172→                if let Err(e) = std::process::Command::new("xdg-open")
173→                    .arg(mount_point.to_str().unwrap_or_default())
174→                    .spawn()
175→                {
176→                    log::error!("Failed to open CipherBox in file manager: {}", e);
177→                }
178→            }
179→        }
180→        "sync" => {
181→            // Trigger immediate sync via the SyncDaemon channel stored in AppState
182→            let state = app.state::<crate::state::AppState>();
183→            if let Some(tx) = state.sync_trigger.read().ok().and_then(|g| g.clone()) {
184→                let _ = tx.try_send(());
185→                log::info!("Manual sync triggered");
186→            } else {
187→                log::warn!("Sync trigger channel not available");
188→            }
189→        }
190→        "login" => {
191→            // Show existing window or create a new one with on_new_window
192→            // handler for OAuth popups.
193→            if let Some(window) = app.get_webview_window("main") {
194→                // Reload page to reset stale DOM & Web3Auth state after logout
195→                let _ = window.eval("location.reload()");
196→                let _ = window.show();
197→                let _ = window.set_focus();
198→            } else {
199→                log::info!("Creating login webview window");
200→                match tauri::WebviewWindowBuilder::new(
201→                    app,
202→                    "main",
203→                    tauri::WebviewUrl::App("index.html".into()),
204→                )
205→                .title("CipherBox")
206→                .inner_size(480.0, 600.0)
207→                .center()
208→                .resizable(false)
209→                .on_new_window({
210→                    let app_handle = app.clone();
211→                    move |url, features| {
212→                        // Create popup with shared WKWebViewConfiguration so
213→                        // window.opener is preserved for OAuth postMessage callbacks
214→                        let n = POPUP_COUNTER.fetch_add(1, Ordering::Relaxed);
215→                        let label = format!("oauth-popup-{}", n);
216→                        match tauri::WebviewWindowBuilder::new(
217→                            &app_handle,
218→                            &label,
219→                            tauri::WebviewUrl::External("about:blank".parse().unwrap()),
220→                        )
221→                        .window_features(features)
222→                        .title(url.as_str())
223→                        .inner_size(500.0, 700.0)
224→                        .center()
225→                        .build()
226→                        {
227→                            Ok(window) => tauri::webview::NewWindowResponse::Create { window },
228→                            Err(e) => {
229→                                log::error!("Failed to create OAuth popup: {}", e);
230→                                tauri::webview::NewWindowResponse::Deny
231→                            }
232→                        }
233→                    }
234→                })
235→                .build()
236→                {
237→                    Ok(window) => {
238→                        let _ = window.show();
239→                        let _ = window.set_focus();
240→                    }
241→                    Err(e) => {
242→                        log::error!("Failed to create login window: {}", e);
243→                    }
244→                }
245→            }
246→        }
247→        "logout" => {
248→            let app_handle = app.clone();
249→            tauri::async_runtime::spawn(async move {
250→                let state = app_handle.state::<crate::state::AppState>();
251→
252→                // Unmount filesystem (FUSE on macOS, WinFsp on Windows)
253→                #[cfg(any(feature = "fuse", feature = "winfsp"))]
254→                {
255→                    if let Err(e) = crate::fuse::unmount_filesystem() {
256→                        log::warn!("Filesystem unmount during logout failed: {}", e);
257→                    }
258→                    *state.mount_status.write().await = crate::state::MountStatus::Unmounted;
259→                }
260→
261→                // POST /auth/logout (best-effort)
262→                let _ = state.sdk.api.authenticated_post("/auth/logout", &()).await;
263→
264→                // Delete refresh token from Keychain
265→                if let Some(ref user_id) = *state.sdk.user_id.read().await {
266→                    let _ = crate::keychain::delete_refresh_token(user_id);
267→                }
268→
269→                // Zero all sensitive keys
270→                state.clear_keys().await;
271→
272→                // Update tray status
273→                if let Err(e) = update_tray_status(&app_handle, &TrayStatus::NotConnected) {
274→                    log::warn!("Failed to update tray status after logout: {}", e);
275→                }
276→
277→                log::info!("Logout complete (via tray menu)");
278→            });
279→        }
280→        "check_updates" => {
281→            crate::updater::manual_check(app);
282→        }
283→        "quit" => {
284→            // Unmount filesystem if mounted, then exit
285→            #[cfg(any(feature = "fuse", feature = "winfsp"))]
286→            {
287→                let _ = crate::fuse::unmount_filesystem();
288→            }
289→            app.exit(0);
290→        }
291→        _ => {
292→            log::debug!("Unknown tray menu event: {}", id);
293→        }
294→    }
295→}
