297→/// Update the tray menu to reflect the new status.
298→///
299→/// Rebuilds the entire menu with updated item states and sets it on the tray icon.
300→/// On Error status, sends a system notification.
301→pub fn update_tray_status(app: &AppHandle, status: &TrayStatus) -> Result<(), String> {
302→    let tray = app
303→        .tray_by_id(TRAY_ID)
304→        .ok_or_else(|| "Tray icon not found".to_string())?;
305→
306→    // Rebuild the menu with updated states
307→    let menu = build_menu(app, status)?;
308→    tray.set_menu(Some(menu))
309→        .map_err(|e| format!("Failed to set tray menu: {}", e))?;
310→
311→    // Send notification on Error status
312→    if let TrayStatus::Error(ref msg) = status {
313→        if let Err(e) = send_error_notification(app, msg) {
314→            log::warn!("Failed to send error notification: {}", e);
315→        }
316→    }
317→
318→    log::debug!("Tray status updated to: {}", status.label());
319→    Ok(())
320→}
