172→    /// Return file attributes for an inode.
173→    pub fn handle_getattr(
174→        fs: &mut CipherBoxFS,
175→        ino: u64,
176→        reply: ReplyAttr,
177→    ) {
178→        fs.drain_upload_completions();
179→
