125→    pub async fn publish_file_metadata(
126→        api: &cipherbox_api_client::ApiClient,
127→        file_meta: &cipherbox_core::FileMetadata,
128→        folder_key: &[u8],
129→        file_ipns_private_key: &zeroize::Zeroizing<Vec<u8>>,
130→        file_ipns_name: &str,
131→        coordinator: &crate::PublishCoordinator,
132→        tee_public_key: Option<&[u8]>,
133→        tee_key_epoch: Option<u32>,
134→        is_first_publish: bool,
135→    ) -> Result<(), String> {
136→        let folder_key_arr: [u8; 32] = folder_key.try_into()
137→            .map_err(|_| "Invalid folder key length for FileMetadata encryption".to_string())?;
138→
139→        let sealed = cipherbox_core::folder::encrypt_file_metadata(file_meta, &folder_key_arr)
140→            .map_err(|e| format!("FileMetadata encryption failed: {}", e))?;
141→
142→        let iv_hex = hex::encode(&sealed[..12]);
143→        use base64::Engine;
144→        let data_base64 = base64::engine::general_purpose::STANDARD.encode(&sealed[12..]);
145→        let json = serde_json::json!({ "iv": iv_hex, "data": data_base64 });
146→        let json_bytes = serde_json::to_vec(&json)
147→            .map_err(|e| format!("FileMetadata JSON serialization failed: {}", e))?;
148→
149→        let file_meta_cid = cipherbox_api_client::ipfs::upload_content(api, &json_bytes)
150→            .await.map_err(|e| format!("{}", e))?;
151→
152→        let seq = coordinator.resolve_sequence(api, file_ipns_name).await?;
153→
154→        let ipns_key_arr: [u8; 32] = file_ipns_private_key.as_slice().try_into()
155→            .map_err(|_| "Invalid file IPNS private key length".to_string())?;
156→        let new_seq = seq + 1;
157→        let value = format!("/ipfs/{}", file_meta_cid);
158→        let record = cipherbox_core::create_ipns_record(&ipns_key_arr, &value, new_seq, 86_400_000)
159→            .map_err(|e| format!("File IPNS record creation failed: {}", e))?;
160→        let marshaled = cipherbox_core::marshal_ipns_record(&record)
161→            .map_err(|e| format!("File IPNS record marshal failed: {}", e))?;
162→
163→        let record_b64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
164→
165→        // TEE enrollment on first publish only (same pattern as folder creation in write_ops.rs:499)
166→        let encrypted_ipns_for_tee = if is_first_publish {
167→            if let Some(tee_key) = tee_public_key {
168→                let wrapped = cipherbox_crypto::wrap_key(
169→                    file_ipns_private_key.as_slice(), tee_key
170→                ).map_err(|e| format!("TEE key wrapping failed: {}", e))?;
171→                Some(hex::encode(&wrapped))
172→            } else {
173→                None
174→            }
175→        } else {
176→            None
177→        };
178→        let has_tee_enrollment = encrypted_ipns_for_tee.is_some();
179→
180→        let req = cipherbox_api_client::IpnsPublishRequest {
181→            ipns_name: file_ipns_name.to_string(),
182→            record: record_b64,
183→            metadata_cid: file_meta_cid.clone(),
184→            encrypted_ipns_private_key: encrypted_ipns_for_tee,
185→            key_epoch: if has_tee_enrollment { tee_key_epoch } else { None },
186→            expected_sequence_number: None,
187→        };
188→        match cipherbox_api_client::ipns::publish_ipns(api, &req).await.map_err(|e| format!("{}", e))? {
189→            cipherbox_api_client::PublishResult::Success => {}
190→            cipherbox_api_client::PublishResult::Conflict { .. } => {
191→                log::warn!("Unexpected conflict on per-file IPNS publish for {}", file_ipns_name);
192→            }
193→        }
194→
195→        coordinator.record_publish(file_ipns_name, new_seq);
196→        log::info!("Per-file IPNS publish succeeded for {}", file_ipns_name);
197→        Ok(())
198→    }
